build() {
    # Keep cargo's registry and download cache inside the build directory
    # rather than in root's home in the shared build root.
    export CARGO_HOME="$PWD/.cargo-home"
    # The book's command. --locked: build exactly the crate versions in
    # upstream's Cargo.lock.
    cargo build --release --locked

    # The book's completion files, generated by the new binary.
    target/release/bindgen --generate-shell-completions bash > bindgen.bash
    target/release/bindgen --generate-shell-completions zsh > _bindgen
}

package() {
    install -Dm755 target/release/bindgen "$DESTDIR/usr/bin/bindgen"
    install -Dm644 bindgen.bash "$DESTDIR/usr/share/bash-completion/completions/bindgen"
    install -Dm644 _bindgen "$DESTDIR/usr/share/zsh/site-functions/_bindgen"
}
